"use strict";
// Published theory only; no exercise answers or grading data. Generated by scripts/build_infinitive_gerund_rule.py.
const INFINITIVE_GERUND_RULE_CONTENT = "<div class=\"mv sv ig\" id=\"ig-root\" lang=\"ru\">\n<header class=\"mv-hero sv-hero\" id=\"ig-map\">\n  <h1>to do · do · doing</h1>\n  <p>Инфинитив и герундий. Какую форму взять, решает слово перед глаголом, а иногда смысл. Нажмите на форму.</p>\n</header>\n<div class=\"sv-lenses ig-lenses\" role=\"group\" aria-label=\"Три формы\"><button type=\"button\" class=\"sv-lens ig-to on\" data-v=\"to\" aria-pressed=\"true\"><span class=\"sv-icon\" aria-hidden=\"true\">→</span><span class=\"sv-word\">to do</span><span class=\"sv-focus\">Цель, план, впереди</span></button><button type=\"button\" class=\"sv-lens ig-bare\" data-v=\"bare\" aria-pressed=\"false\"><span class=\"sv-icon\" aria-hidden=\"true\">∅</span><span class=\"sv-word\">do</span><span class=\"sv-focus\">Без to</span></button><button type=\"button\" class=\"sv-lens ig-ing\" data-v=\"ing\" aria-pressed=\"false\"><span class=\"sv-icon\" aria-hidden=\"true\">~ing</span><span class=\"sv-word\">doing</span><span class=\"sv-focus\">Процесс, опыт, факт</span></button></div><div class=\"sv-lpanels\" aria-live=\"polite\"><div class=\"sv-lp ig-to\" data-v=\"to\"><p class=\"sv-lp-h\"><span class=\"sv-v ig-to\">to do</span> <span>Действие ещё впереди: хотим, решаем, обещаем, идём, чтобы сделать</span></p><div class=\"sv-pats\"><code>want <b>to go</b></code><code>decide <b>to stay</b></code><code>easy <b>to read</b></code><code>came <b>to help</b></code></div><ul class=\"sv-exs\"><li>We decided <b>to stay</b> at home.</li><li>It’s hard <b>to explain</b>.</li><li>She called <b>to say</b> sorry.</li></ul><p class=\"sv-lp-n\">После глаголов желания и решения, после прилагательных, для цели. Русское «чтобы» — почти всегда <b>to do</b>.</p></div><div class=\"sv-lp ig-bare\" data-v=\"bare\" hidden><p class=\"sv-lp-h\"><span class=\"sv-v ig-bare\">do</span> <span>Голый инфинитив: начальная форма без частицы</span></p><div class=\"sv-pats\"><code>can <b>swim</b></code><code>make sb <b>laugh</b></code><code>let sb <b>stay</b></code><code>had better <b>go</b></code></div><ul class=\"sv-exs\"><li>You must <b>see</b> this film.</li><li>They made us <b>wait</b>.</li><li>Why not <b>ask</b> her?</li></ul><p class=\"sv-lp-n\">После модальных глаголов, make / let, had better, would rather, why not. Таких слов немного — их можно выучить списком.</p></div><div class=\"sv-lp ig-ing\" data-v=\"ing\" hidden><p class=\"sv-lp-h\"><span class=\"sv-v ig-ing\">doing</span> <span>Действие как занятие: оно уже идёт, уже было или просто «явление»</span></p><div class=\"sv-pats\"><code>enjoy <b>swimming</b></code><code>good at <b>drawing</b></code><code>look forward to <b>seeing</b></code><code><b>Walking</b> is fun.</code></div><ul class=\"sv-exs\"><li>I enjoy <b>cooking</b> for friends.</li><li>Thanks for <b>coming</b>.</li><li>He left without <b>saying</b> goodbye.</li></ul><p class=\"sv-lp-n\">После любого предлога — только <b>-ing</b>. После глаголов удовольствия, избегания, окончания.</p></div></div><p class=\"sv-motto\"><span class=\"ig-to\">Впереди — to do.</span><span class=\"ig-ing\">После предлога — doing.</span><span class=\"ig-bare\">После can, make, let — do.</span><span class=\"ig-both\">stop, try, remember — смотри на смысл.</span></p>\n<nav class=\"mv-nav\" aria-label=\"Разделы правила\">\n  <a href=\"#ig-after\">1 Что перед</a><a href=\"#ig-verb-to\">2 + to do</a><a href=\"#ig-verb-ing\">3 + doing</a><a href=\"#ig-prep\">4 Предлог</a><a href=\"#ig-bare\">5 Без to</a><a href=\"#ig-meaning\">6 Смысл</a><a href=\"#ig-object\">7 Кого-то + …</a><a href=\"#ig-adj\">8 Прилаг. и цель</a><a href=\"#ig-forms\">9 Формы</a><a href=\"#ig-finder\">10 Список</a><a href=\"#ig-traps\">11 Ловушки</a><a href=\"#ig-check\">12 Проверка</a>\n</nav>\n<section class=\"mv-sec\" id=\"ig-after\"><h2><span class=\"mv-num\">1</span>Что стоит перед глаголом?</h2><p class=\"mv-lead\">Выберите слово и посмотрите, какая форма подходит после него.</p><div class=\"sv-board\"><div class=\"sv-slots\" role=\"group\" aria-label=\"Что стоит перед глаголом\"><button type=\"button\" class=\"sv-slot on\" data-s=\"0\" aria-pressed=\"true\"><b>enjoy · avoid · mind</b><small>Глаголы «на -ing»</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"1\" aria-pressed=\"false\"><b>want · decide · hope</b><small>Глаголы «на to»</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"2\" aria-pressed=\"false\"><b>about · of · in · without</b><small>Предлог</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"3\" aria-pressed=\"false\"><b>look forward to</b><small>«to» — это предлог</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"4\" aria-pressed=\"false\"><b>can · must · should</b><small>Модальные глаголы</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"5\" aria-pressed=\"false\"><b>make · let + кого-то</b><small>Заставить, позволить</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"6\" aria-pressed=\"false\"><b>see · hear + кого-то</b><small>Видел, слышал</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"7\" aria-pressed=\"false\"><b>stop · remember · try</b><small>Смысл меняется</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"8\" aria-pressed=\"false\"><b>begin · start · continue</b><small>Разницы почти нет</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"9\" aria-pressed=\"false\"><b>easy · happy · ready</b><small>Прилагательное</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"10\" aria-pressed=\"false\"><b>too · enough</b><small>Слишком, достаточно</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"11\" aria-pressed=\"false\"><b>had better · would rather</b><small>Лучше бы, предпочёл бы</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"12\" aria-pressed=\"false\"><b>The car needs …</b><small>Вещь нуждается</small></button><button type=\"button\" class=\"sv-slot\" data-s=\"13\" aria-pressed=\"false\"><b>«чтобы» (цель)</b><small>Зачем?</small></button></div><div class=\"sv-result\" aria-live=\"polite\"><div class=\"sv-sd\" data-s=\"0\"><p class=\"sv-sd-h\"><b>enjoy · avoid · mind</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-n\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">enjoy to swim</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-y\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">I enjoy swimming.</span></div></div><p class=\"sv-sd-n\">Удовольствие, избегание, окончание: enjoy, avoid, mind, finish, give up, keep, can’t stand. <a href=\"#ig-verb-ing\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"1\" hidden><p class=\"sv-sd-h\"><b>want · decide · hope</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-y\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">We decided to stay.</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-n\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">decided staying</span></div></div><p class=\"sv-sd-n\">Желание, план, решение, обещание: want, hope, plan, decide, promise, refuse, manage. <a href=\"#ig-verb-to\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"2\" hidden><p class=\"sv-sd-h\"><b>about · of · in · without</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-n\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">good at to draw</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-y\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">She’s good at drawing.</span></div></div><p class=\"sv-sd-n\">После предлога глагол всегда с <b>-ing</b>: interested in, tired of, before, after, without, instead of. <a href=\"#ig-prep\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"3\" hidden><p class=\"sv-sd-h\"><b>look forward to</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-n\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">look forward to see</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-y\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">I look forward to seeing you.</span></div></div><p class=\"sv-sd-n\">Проверка: подставьте существительное. <i>look forward to the party</i> — значит, to здесь предлог, и дальше <b>-ing</b>. <a href=\"#ig-to-prep\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"4\" hidden><p class=\"sv-sd-h\"><b>can · must · should</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-n\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">must to go</span></div><div class=\"sv-lamp ig-bare sv-y\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">You must go.</span></div><div class=\"sv-lamp ig-ing sv-n\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div></div><p class=\"sv-sd-n\">После can, could, must, should, may, might, will, would — глагол без to. <a href=\"#ig-modal\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"5\" hidden><p class=\"sv-sd-h\"><b>make · let + кого-то</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-p\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">В пассиве: I was made to wait.</span></div><div class=\"sv-lamp ig-bare sv-y\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">They made me wait.</span></div><div class=\"sv-lamp ig-ing sv-n\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div></div><p class=\"sv-sd-n\">make / let sb <b>do</b>. В пассиве у make возвращается to: <i>was made to wait</i>; у let пассива нет — <i>was allowed to</i>. <a href=\"#ig-make-let\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"6\" hidden><p class=\"sv-sd-h\"><b>see · hear + кого-то</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-p\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">В пассиве: He was seen to leave.</span></div><div class=\"sv-lamp ig-bare sv-y\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">I saw him fall. — целиком</span></div><div class=\"sv-lamp ig-ing sv-y\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">I saw him falling. — в процессе</span></div></div><p class=\"sv-sd-n\">Целое событие — <b>do</b>, кусочек процесса — <b>doing</b>. <a href=\"#ig-senses\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"7\" hidden><p class=\"sv-sd-h\"><b>stop · remember · try</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-y\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">He stopped to rest. — чтобы отдохнуть</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-y\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">He stopped smoking. — бросил</span></div></div><p class=\"sv-sd-n\">Обе формы верны, но это разные предложения. Подробно — в разделе 6. <a href=\"#ig-meaning\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"8\" hidden><p class=\"sv-sd-h\"><b>begin · start · continue</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-y\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">It began to rain.</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-y\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">It began raining.</span></div></div><p class=\"sv-sd-n\">begin, start, continue, intend, bother — обе формы. Но после -ing-формы берите to: <i>It’s starting to rain</i>. <a href=\"#ig-same\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"9\" hidden><p class=\"sv-sd-h\"><b>easy · happy · ready</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-y\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">This app is easy to use.</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-p\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">Только worth и busy: worth seeing</span></div></div><p class=\"sv-sd-n\">Прилагательное + <b>to do</b>. Исключения на -ing: <i>worth</i>, <i>busy</i>, а также прилагательные с предлогом (<i>good at</i>). <a href=\"#ig-adj-to\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"10\" hidden><p class=\"sv-sd-h\"><b>too · enough</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-y\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">too tired to drive</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-n\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">too tired for driving</span></div></div><p class=\"sv-sd-n\">too + прилагательное + to do; прилагательное + enough + to do. <a href=\"#ig-too\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"11\" hidden><p class=\"sv-sd-h\"><b>had better · would rather</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-n\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">had better to go</span></div><div class=\"sv-lamp ig-bare sv-y\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">You’d better hurry.</span></div><div class=\"sv-lamp ig-ing sv-n\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div></div><p class=\"sv-sd-n\">had better, would rather, would sooner, why not, rather than — без to. <a href=\"#ig-rather\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"12\" hidden><p class=\"sv-sd-h\"><b>The car needs …</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-p\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">needs to be repaired</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-y\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">The car needs repairing.</span></div></div><p class=\"sv-sd-n\">О предмете: needs <b>doing</b> = needs <b>to be done</b>. О человеке: <i>I need to repair it.</i> <a href=\"#ig-needs\">Подробнее →</a></p></div><div class=\"sv-sd\" data-s=\"13\" hidden><p class=\"sv-sd-h\"><b>«чтобы» (цель)</b> + …</p><div class=\"sv-lamps ig-lamps\"><div class=\"sv-lamp ig-to sv-y\"><span class=\"sv-lamp-v\">to do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">I came to help.</span></div><div class=\"sv-lamp ig-bare sv-n\"><span class=\"sv-lamp-v\">do</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\"></span></div><div class=\"sv-lamp ig-ing sv-p\"><span class=\"sv-lamp-v\">doing</span><span class=\"sv-lamp-s\"></span><span class=\"sv-lamp-e\">Только о назначении вещи: a knife for cutting</span></div></div><p class=\"sv-sd-n\">Цель человека — <b>to do</b> (in order to, so as to). <i>for + -ing</i> — для чего служит предмет. <a href=\"#ig-purpose\">Подробнее →</a></p></div></div><p class=\"sv-legend\"><span class=\"sv-k sv-y\">✓ подходит</span><span class=\"sv-k sv-p\">✓ с условием</span><span class=\"sv-k sv-n\">✗ нельзя</span></p></div></section>\n<section class=\"mv-sec\" id=\"ig-verb-to\"><h2><span class=\"mv-num\">2</span>Глагол + to do</h2><p class=\"mv-lead\">Чаще всего — действие впереди: хочу, решил, обещаю, удалось.</p><div class=\"sv-rows\"><details class=\"sv-row ig-to\" id=\"ig-want\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Желания и планы<small>want · would like · hope · plan · intend · expect</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I want to learn Japanese.</li><li>We’re planning to move in spring.</li><li>I hope to see you soon.</li><li>Would you like to join us?</li><li class=\"sv-no\"><s>I hope seeing you soon.</s></li></ul><p class=\"sv-rn\">Сюда же: aim, wish, can’t wait, would love / prefer. <b>would like</b> — только to.</p></div></details><details class=\"sv-row ig-to\" id=\"ig-decide\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Решения, обещания, отказ<small>decide · agree · refuse · promise · offer</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>They decided to sell the house.</li><li>She refused to answer.</li><li>He promised not to be late.</li><li>My brother offered to help.</li><li>We agreed to meet at six.</li></ul><p class=\"sv-rn\">Также: choose, threaten, arrange, prepare, demand, ask (to do).</p></div></details><details class=\"sv-row ig-to\" id=\"ig-manage\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Удалось или нет<small>manage · fail · afford · attempt · learn</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Did you manage to find the hotel?</li><li>He failed to notice the sign.</li><li>We can’t afford to buy a car.</li><li>She learnt to swim at five.</li><li>Don’t hesitate to ask.</li></ul><p class=\"sv-rn\">Также: deserve, tend, hesitate, struggle, can’t wait.</p></div></details><details class=\"sv-row ig-to\" id=\"ig-seem\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Кажется, оказалось<small>seem · appear · pretend · happen · tend</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>She seems to know everyone.</li><li>He pretended to be asleep.</li><li>I happened to see her at the station.</li><li>Prices tend to rise in summer.</li><li>The plan turned out to be a disaster.</li></ul><p class=\"sv-rn\">happen to do — «случайно сделать», pretend to do — «притворяться».</p></div></details><details class=\"sv-row ig-to\" id=\"ig-wh\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Вопросительное слово + to<small>how to · what to · where to · whether to</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I don’t know what to say.</li><li>Can you show me how to use it?</li><li>She couldn’t decide whether to stay.</li><li>Tell me where to put the box.</li></ul><p class=\"sv-rn\">После know, learn, show, explain, wonder, decide: «как сделать», «что сказать».</p></div></details></div></section>\n<section class=\"mv-sec\" id=\"ig-verb-ing\"><h2><span class=\"mv-num\">3</span>Глагол + doing</h2><p class=\"mv-lead\">Действие как занятие: нравится, избегаю, закончил, предлагаю.</p><div class=\"sv-rows\"><details class=\"sv-row ig-ing\" id=\"ig-enjoy\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Нравится, не нравится<small>enjoy · don’t mind · can’t stand · fancy · feel like</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I really enjoy cooking.</li><li>Do you mind waiting a minute?</li><li>He can’t stand queuing.</li><li>I don’t feel like going out tonight.</li><li class=\"sv-no\"><s>I enjoy to cook.</s></li></ul><p class=\"sv-rn\">Также: dislike, detest, can’t bear (и с to), fancy (UK, «хотеть»).</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-avoid\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Избегать, откладывать, рисковать<small>avoid · put off · postpone · delay · risk · miss</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>She avoided looking at me.</li><li>Stop putting off calling the bank.</li><li>I miss living by the sea.</li><li>You risk losing everything.</li><li>I couldn’t help laughing.</li></ul><p class=\"sv-rn\"><b>can’t help doing</b> — «не могу не…»: <i>I couldn’t help laughing</i>.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-finish\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Закончить, продолжать<small>finish · give up · quit · keep (on) · carry on · practise</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Have you finished packing?</li><li>He gave up eating sugar.</li><li>Keep trying <span class=\"ig-gloss\">— you’re nearly there!</span></li><li>They carried on talking.</li><li>You should practise speaking every day.</li></ul></div></details><details class=\"sv-row ig-ing\" id=\"ig-admit\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Мысли и слова<small>admit · deny · suggest · consider · imagine · mention · involve</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>He admitted taking the money.</li><li>She denied breaking the vase.</li><li>I suggest leaving early.</li><li>Have you considered studying abroad?</li><li>The job involves travelling a lot.</li><li class=\"sv-no\"><s>I suggest to leave early.</s></li></ul><p class=\"sv-rn\">Также: recommend (doing), report, describe, discuss, justify, resent, appreciate.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-go\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">go + -ing и время<small>go swimming · spend time doing · be busy doing</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Let’s go skiing in March.</li><li>We went shopping on Saturday.</li><li>I spent the evening reading.</li><li>Don’t waste time worrying.</li><li>She’s busy writing her essay.</li></ul><p class=\"sv-rn\">go + спорт и развлечения: go fishing, go camping, go dancing.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-worth\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Готовые выражения<small>it’s no use · no point (in) · worth · have trouble (in)</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>It’s no use crying about it.</li><li>There’s no point (in) arguing.</li><li>The museum is worth visiting.</li><li>I had trouble finding the house.</li><li>We had difficulty (in) getting tickets.</li></ul><p class=\"sv-rn\">Также: it’s no good, it’s a waste of time, can’t help, feel like.</p></div></details></div></section>\n<section class=\"mv-sec\" id=\"ig-prep\"><h2><span class=\"mv-num\">4</span>Предлог + doing</h2><p class=\"mv-lead\">Самое надёжное правило темы: после предлога — только -ing.</p><div class=\"ig-formula\"><span class=\"ig-chip\">предлог</span><span class=\"ig-plus\">+</span><span class=\"sv-v ig-ing\">doing</span><p class=\"sv-f-n\">Любой предлог: <i>in, on, at, of, for, about, with, without, before, after, by, instead of</i> — и <b>to</b>, если это предлог.</p></div><div class=\"sv-rows\"><details class=\"sv-row ig-ing\" id=\"ig-prep-verb\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Глагол + предлог<small>think of · insist on · succeed in · apologise for</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I’m thinking of changing jobs.</li><li>He insisted on paying.</li><li>She succeeded in passing the exam.</li><li>I apologise for being late.</li><li>It depends on getting the money.</li></ul><p class=\"sv-rn\">Также: believe in, dream of, rely on, approve of, complain about, worry about, feel like.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-prep-adj\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Прилагательное + предлог<small>good at · interested in · tired of · afraid of · fond of</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>She’s good at solving puzzles.</li><li>Are you interested in joining the club?</li><li>I’m tired of waiting.</li><li>He’s proud of winning.</li><li>They’re keen on hiking.</li></ul><p class=\"sv-rn\">Также: capable of, responsible for, famous for, bored with, worried about, sorry for.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-prep-obj\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Глагол + кого-то + предлог<small>prevent sb from · accuse sb of · thank sb for</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>The rain prevented us from going out.</li><li>They accused him of cheating.</li><li>Thank you for helping me.</li><li>She talked me into buying it.</li><li>Congratulations on passing your test!</li></ul><p class=\"sv-rn\">Также: stop sb (from), blame sb for, warn sb about, discourage sb from, forgive sb for.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-prep-free\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Свободные предлоги<small>before · after · without · instead of · by · on</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Wash your hands before eating.</li><li>He left without saying goodbye.</li><li>Instead of complaining, help me.</li><li>You can save money by cooking at home.</li><li>On arriving, call me.</li><li>Despite feeling ill, she came.</li></ul><p class=\"sv-rn\">Также: besides, apart from, in spite of, despite, as well as, since.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-to-prep\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">«to» — предлог, а не частица<small>look forward to · be / get used to · object to</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I look forward to hearing from you.</li><li>I’m used to getting up early.</li><li>You’ll soon get used to living here.</li><li>I object to being treated like a child.</li><li>I prefer walking to driving.</li><li>When it comes to cooking, he’s the best.</li><li class=\"sv-no\"><s>I look forward to see you.</s></li></ul><p class=\"sv-rn\">Тест: можно ли после to поставить существительное? <i>look forward to the trip</i> — да, значит дальше -ing. Не путайте: <b>used to do</b> — «раньше делал», <b>be used to doing</b> — «привык».</p></div></details></div></section>\n<section class=\"mv-sec\" id=\"ig-bare\"><h2><span class=\"mv-num\">5</span>Инфинитив без to</h2><p class=\"mv-lead\">Короткий закрытый список. Всё остальное — с to.</p><div class=\"sv-rows\"><details class=\"sv-row ig-bare\" id=\"ig-modal\"><summary><span class=\"sv-v ig-bare\">do</span><span class=\"sv-rt\">Модальные глаголы<small>can · must · should · might · will</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>You must try this cake.</li><li>She can’t come today.</li><li>We might go to Rome.</li><li class=\"sv-no\"><s>You must to try it.</s></li></ul><p class=\"sv-rn\">Также после do / does / did в вопросах и отрицаниях. Исключения с to: ought to, have to, be able to, need to.</p></div></details><details class=\"sv-row ig-bare\" id=\"ig-make-let\"><summary><span class=\"sv-v ig-bare\">do</span><span class=\"sv-rt\">make · let · have<small>make / let / have sb do</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>The film made me cry.</li><li>Let me carry that.</li><li>I’ll have the porter bring your bags.</li><li>We were made to wait outside.</li><li>We weren’t allowed to leave.</li><li class=\"sv-no\"><s>They made me to wait.</s></li></ul><p class=\"sv-rn\">Но <b>get sb to do</b> и <b>force sb to do</b> — с to: <i>I got him to fix it.</i></p></div></details><details class=\"sv-row ig-bare\" id=\"ig-help\"><summary><span class=\"sv-v ig-bare\">do</span><span class=\"sv-rt\">help (to) do<small>help sb (to) do</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Can you help me (to) move the sofa?</li><li>This app helps you (to) learn words.</li></ul><p class=\"sv-rn\">Обе формы верны. Без to чаще в разговоре.</p></div></details><details class=\"sv-row ig-bare\" id=\"ig-senses\"><summary><span class=\"sv-v ig-bare\">do</span><span class=\"sv-rt\">see · hear · watch · feel + кого-то<small>do — целиком, doing — процесс</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I saw her cross the road. <span class=\"ig-gloss\">— видел от начала до конца</span></li><li>I saw her crossing the road. <span class=\"ig-gloss\">— видел в процессе</span></li><li>I heard someone call my name.</li><li>We watched the kids playing.</li><li>He was seen to leave at ten.</li></ul><p class=\"sv-rn\">В пассиве — to: <i>was seen to leave</i>, <i>was heard to say</i>.</p></div></details><details class=\"sv-row ig-bare\" id=\"ig-rather\"><summary><span class=\"sv-v ig-bare\">do</span><span class=\"sv-rt\">Лучше, предпочитаю, почему бы не<small>had better · would rather · why not · rather than</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>You’d better take an umbrella.</li><li>I’d rather stay in tonight.</li><li>Why not ask the teacher?</li><li>Why wait? Book it now.</li><li>I’ll walk rather than take a taxi.</li><li class=\"sv-no\"><s>Why to wait?</s></li></ul><p class=\"sv-rn\">Также: would sooner, cannot but (книжно), do nothing but: <i>He did nothing but complain.</i> Но <i>had no choice but <b>to</b> agree</i>.</p></div></details></div></section>\n<section class=\"mv-sec\" id=\"ig-meaning\"><h2><span class=\"mv-num\">6</span>Обе формы, но смысл разный</h2><p class=\"mv-lead\">Переключайте to do и doing и сравнивайте.</p><div class=\"ig-pairs\" aria-live=\"polite\"><div class=\"ig-pair\" id=\"ig-remember\"><div class=\"ig-ph\"><b>remember</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"remember + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">не забыть сделать</p><p class=\"ig-sample\">Remember to lock the door.</p><p class=\"ig-ru\">Не забудь запереть дверь.</p><p class=\"ig-order\">сначала помню → потом делаю</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">помнить, как делал</p><p class=\"ig-sample\">I remember locking the door.</p><p class=\"ig-ru\">Помню, что запер дверь.</p><p class=\"ig-order\">сначала сделал → потом помню</p></div></div><div class=\"ig-pair\" id=\"ig-forget\"><div class=\"ig-ph\"><b>forget</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"forget + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">забыть сделать</p><p class=\"ig-sample\">I forgot to call her.</p><p class=\"ig-ru\">Я забыл ей позвонить.</p><p class=\"ig-order\">не сделал</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">забыть то, что было</p><p class=\"ig-sample\">I’ll never forget seeing the sea for the first time.</p><p class=\"ig-ru\">Никогда не забуду, как впервые увидел море.</p><p class=\"ig-order\">было → не забуду</p></div></div><div class=\"ig-pair\" id=\"ig-stop\"><div class=\"ig-ph\"><b>stop</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"stop + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">остановиться, чтобы…</p><p class=\"ig-sample\">We stopped to buy some water.</p><p class=\"ig-ru\">Мы остановились, чтобы купить воды.</p><p class=\"ig-order\">остановились → потом купили</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">перестать, бросить</p><p class=\"ig-sample\">He stopped smoking last year.</p><p class=\"ig-ru\">Он бросил курить в прошлом году.</p><p class=\"ig-order\">делал → перестал</p></div></div><div class=\"ig-pair\" id=\"ig-try\"><div class=\"ig-ph\"><b>try</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"try + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">пытаться (трудно)</p><p class=\"ig-sample\">I tried to open the window, but it was stuck.</p><p class=\"ig-ru\">Я пытался открыть окно, но его заело.</p><p class=\"ig-order\">усилие, может не получиться</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">попробовать как способ</p><p class=\"ig-sample\">Try opening the window — it might help.</p><p class=\"ig-ru\">Попробуй открыть окно — может, поможет.</p><p class=\"ig-order\">сделать легко, вопрос — поможет ли</p></div></div><div class=\"ig-pair\" id=\"ig-regret\"><div class=\"ig-ph\"><b>regret</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"regret + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">с сожалением сообщаю</p><p class=\"ig-sample\">We regret to inform you that the flight is cancelled.</p><p class=\"ig-ru\">С сожалением сообщаем, что рейс отменён.</p><p class=\"ig-order\">сейчас; inform, tell, say, announce</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">жалеть о сделанном</p><p class=\"ig-sample\">I regret telling him the truth.</p><p class=\"ig-ru\">Жалею, что сказал ему правду.</p><p class=\"ig-order\">было → жалею</p></div></div><div class=\"ig-pair\" id=\"ig-go-on\"><div class=\"ig-ph\"><b>go on</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"go on + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">перейти к следующему</p><p class=\"ig-sample\">After school, she went on to study law.</p><p class=\"ig-ru\">После школы она пошла учиться на юриста.</p><p class=\"ig-order\">одно → потом другое</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">продолжать то же</p><p class=\"ig-sample\">He went on talking for an hour.</p><p class=\"ig-ru\">Он продолжал говорить ещё час.</p><p class=\"ig-order\">то же самое дальше</p></div></div><div class=\"ig-pair\" id=\"ig-mean\"><div class=\"ig-ph\"><b>mean</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"mean + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">собираться, намереваться</p><p class=\"ig-sample\">I meant to call you, but I forgot.</p><p class=\"ig-ru\">Я собирался тебе позвонить, но забыл.</p><p class=\"ig-order\">намерение</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">означать, влечь за собой</p><p class=\"ig-sample\">The new job means moving to Leeds.</p><p class=\"ig-ru\">Новая работа означает переезд в Лидс.</p><p class=\"ig-order\">следствие</p></div></div><div class=\"ig-pair\" id=\"ig-need\"><div class=\"ig-ph\"><b>need</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"need + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">человеку нужно сделать</p><p class=\"ig-sample\">I need to wash the car.</p><p class=\"ig-ru\">Мне нужно помыть машину.</p><p class=\"ig-order\">кто-то сделает</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">вещь нуждается</p><p class=\"ig-sample\">The car needs washing.</p><p class=\"ig-ru\">Машину нужно помыть.</p><p class=\"ig-order\">= needs to be washed</p></div></div><div class=\"ig-pair\" id=\"ig-afraid\"><div class=\"ig-ph\"><b>be afraid</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"be afraid + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">боюсь и не решаюсь</p><p class=\"ig-sample\">She was afraid to ask.</p><p class=\"ig-ru\">Она боялась (не решалась) спросить.</p><p class=\"ig-order\">зависит от меня</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">боюсь, что случится</p><p class=\"ig-sample\">I’m afraid of falling.</p><p class=\"ig-ru\">Боюсь упасть.</p><p class=\"ig-order\">может случиться само</p></div></div><div class=\"ig-pair\" id=\"ig-sorry\"><div class=\"ig-ph\"><b>be sorry</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"be sorry + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">сожалею сейчас</p><p class=\"ig-sample\">I’m sorry to hear that.</p><p class=\"ig-ru\">Жаль это слышать.</p><p class=\"ig-order\">сейчас или сразу после</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">извиняюсь за прошлое</p><p class=\"ig-sample\">I’m sorry for being late.</p><p class=\"ig-ru\">Извини, что опоздал.</p><p class=\"ig-order\">было → извиняюсь</p></div></div><div class=\"ig-pair\" id=\"ig-interested\"><div class=\"ig-ph\"><b>be interested</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"be interested + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">интересно узнать</p><p class=\"ig-sample\">I’d be interested to hear your opinion.</p><p class=\"ig-ru\">Мне было бы интересно узнать ваше мнение.</p><p class=\"ig-order\">hear, know, learn, see</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">интересуюсь, хочу заниматься</p><p class=\"ig-sample\">I’m interested in learning Spanish.</p><p class=\"ig-ru\">Мне интересно изучать испанский.</p><p class=\"ig-order\">занятие</p></div></div><div class=\"ig-pair\" id=\"ig-like\"><div class=\"ig-ph\"><b>like</b><div class=\"ig-pbs\" role=\"group\" aria-label=\"like + …\"><button type=\"button\" class=\"ig-pb ig-to on\" data-k=\"to\" aria-pressed=\"true\">+ to do</button><button type=\"button\" class=\"ig-pb ig-ing\" data-k=\"ing\" aria-pressed=\"false\">+ doing</button></div></div><div class=\"ig-pp ig-to\" data-k=\"to\"><p class=\"ig-sense\">предпочитаю так делать</p><p class=\"ig-sample\">I like to see the dentist twice a year.</p><p class=\"ig-ru\">Я стараюсь ходить к стоматологу дважды в год.</p><p class=\"ig-order\">считаю правильным</p></div><div class=\"ig-pp ig-ing\" data-k=\"ing\" hidden><p class=\"ig-sense\">получаю удовольствие</p><p class=\"ig-sample\">I like swimming.</p><p class=\"ig-ru\">Я люблю плавать.</p><p class=\"ig-order\">нравится само занятие</p></div></div></div><div class=\"sv-rows\"><details class=\"sv-row ig-both\" id=\"ig-same\"><summary><span class=\"sv-v ig-both\">to / -ing</span><span class=\"sv-rt\">Обе формы, смысл тот же<small>begin · start · continue · intend · bother</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>It started to rain / raining.</li><li>She continued to work / working.</li><li>Don’t bother to call / calling.</li><li>It’s starting to rain. <span class=\"ig-gloss\">— не starting raining</span></li></ul><p class=\"sv-rn\">Если сам главный глагол стоит в -ing, берите to, чтобы не было двух -ing подряд.</p></div></details><details class=\"sv-row ig-both\" id=\"ig-love\"><summary><span class=\"sv-v ig-both\">to / -ing</span><span class=\"sv-rt\">love · hate · prefer · can’t bear<small>почти без разницы</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I love dancing / to dance.</li><li>She hates being late / to be late.</li><li>I prefer to walk / walking.</li><li>I’d love to come. <span class=\"ig-gloss\">— только to</span></li><li>I prefer walking to driving.</li><li>I’d rather walk than drive.</li></ul><p class=\"sv-rn\">С would — только to: <i>would like / love / hate / prefer to do</i>. Сравнение: prefer <b>doing</b> X <b>to doing</b> Y.</p></div></details><details class=\"sv-row ig-both\" id=\"ig-used\"><summary><span class=\"sv-v ig-both\">to / -ing</span><span class=\"sv-rt\">used to do · be used to doing<small>раньше делал · привык</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I used to live in Kazan. <span class=\"ig-gloss\">— раньше жил</span></li><li>I’m used to living alone. <span class=\"ig-gloss\">— привык</span></li><li>She’ll get used to working nights. <span class=\"ig-gloss\">— привыкнет</span></li></ul></div></details></div></section>\n<section class=\"mv-sec\" id=\"ig-object\"><h2><span class=\"mv-num\">7</span>Глагол + кого-то + …</h2><p class=\"mv-lead\">Когда после глагола появляется человек, схема часто меняется.</p><div class=\"sv-rows\"><details class=\"sv-row ig-to\" id=\"ig-obj-to\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Глагол + кого-то + to do<small>want · ask · tell · advise · allow · expect · remind</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I want you to listen.</li><li>She asked me to wait.</li><li>They told us not to worry.</li><li>Mum reminded me to call Grandma.</li><li>Nobody expected him to win.</li><li class=\"sv-no\"><s>I want that you listen.</s></li></ul><p class=\"sv-rn\">Также: would like, invite, encourage, persuade, force, order, teach, warn (not to), get, enable, allow, permit.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-obj-ing\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Без объекта → -ing<small>allow · permit · advise · recommend · forbid + doing</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>They don’t allow smoking here.</li><li>They don’t allow us to smoke here.</li><li>I’d advise booking early.</li><li>I’d advise you to book early.</li><li>Smoking is not allowed.</li><li>We aren’t allowed to smoke.</li></ul><p class=\"sv-rn\">С человеком — <b>to do</b>, без человека — <b>-ing</b>.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-suggest\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">suggest · recommend<small>suggest doing · suggest (that) sb do</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>She suggested going by train.</li><li>She suggested (that) we go by train.</li><li>I recommend booking a table.</li><li>I recommend that you book a table.</li><li class=\"sv-no\"><s>She suggested me to go.</s></li></ul><p class=\"sv-rn\">После suggest человек + to do невозможен. <i>Recommend sb to do</i> встречается в британском английском, но надёжнее <i>recommend that…</i> или <i>recommend doing</i>.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-forbid\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Запретить, помешать<small>forbid sb to do / from doing · prevent sb from doing</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Her parents forbade her to go out.</li><li>He forbade them from mentioning it.</li><li>Nothing can prevent us from leaving.</li><li>Stop him (from) eating the cake!</li></ul><p class=\"sv-rn\">prevent / stop / discourage sb <b>from doing</b>.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-poss\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Кто делает: my / me / Tom’s + -ing<small>Do you mind my opening…?</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Do you mind my / me opening the window?</li><li>I don’t like him / his shouting at people.</li><li>We appreciate your helping us.</li><li>It’s important for us to be on time.</li></ul><p class=\"sv-rn\">Притяжательное (my, his) — более официально, объектное (me, him) — разговорно. С инфинитивом исполнитель вводится через <b>for</b>.</p></div></details><details class=\"sv-row ig-to\" id=\"ig-believe\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">считать, знать кого-то + to be<small>consider / believe / find sb to be</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>We consider him to be the best candidate.</li><li>I found her to be very helpful.</li><li>He is said to be very rich.</li><li>She is believed to have left the country.</li></ul><p class=\"sv-rn\">Это книжный стиль. В разговоре: <i>I think he’s the best.</i> Пассивные формы — в разделе 9.</p></div></details></div></section>\n<section class=\"mv-sec\" id=\"ig-adj\"><h2><span class=\"mv-num\">8</span>Прилагательные, существительные, цель</h2><p class=\"mv-lead\">После прилагательного и существительного обычно to do.</p><div class=\"sv-rows\"><details class=\"sv-row ig-to\" id=\"ig-adj-to\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Прилагательное + to do<small>easy · hard · nice · glad · ready · likely · sure</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>This book is easy to read.</li><li>I’m glad to hear that.</li><li>Are you ready to order?</li><li>He’s likely to be late.</li><li>She’s sure to win.</li><li>It’s kind of you to help.</li></ul><p class=\"sv-rn\">Оценка человека: <i>It’s kind / silly / clever <b>of</b> you to…</i>; оценка действия: <i>It’s easy <b>for</b> me to…</i></p></div></details><details class=\"sv-row ig-to\" id=\"ig-too\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">too · enough<small>too + adj + to · adj + enough + to</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>She’s too young to drive.</li><li>He’s old enough to vote.</li><li>It’s too cold for us to swim.</li><li>There isn’t enough time to finish.</li><li class=\"sv-no\"><s>He isn’t enough old.</s></li></ul><p class=\"sv-rn\">enough стоит <b>после</b> прилагательного, но <b>перед</b> существительным: old enough, enough time.</p></div></details><details class=\"sv-row ig-to\" id=\"ig-first\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">the first / last / only + to<small>the first to arrive</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>She was the first to arrive.</li><li>He’s the only one to pass.</li><li>The last person to leave turns off the lights.</li></ul><p class=\"sv-rn\">Также с порядковыми: the second / next to do.</p></div></details><details class=\"sv-row ig-to\" id=\"ig-noun-to\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Существительное + to do<small>a chance to · time to · nothing to do · a book to read</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>It’s time to go.</li><li>I have nothing to wear.</li><li>We need somewhere to stay.</li><li>There’s no one to talk to.</li><li>Her decision to leave surprised us.</li></ul><p class=\"sv-rn\">Но у части существительных — of + -ing: <i>the idea of moving</i>, <i>the chance of winning</i> (вероятность), <i>the thought of leaving</i>.</p></div></details><details class=\"sv-row ig-to\" id=\"ig-purpose\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Цель: чтобы<small>to · in order to · so as (not) to</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I went out to buy some bread.</li><li>She saved money in order to travel.</li><li>We left early so as not to miss the train.</li><li>This tool is for cutting glass.</li><li class=\"sv-no\"><s>I came here for learning English.</s></li></ul><p class=\"sv-rn\">Цель человека — <b>to do</b>. <b>for + -ing</b> — назначение предмета. «Чтобы не» — <i>so as not to / in order not to</i>.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-subject\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">-ing как подлежащее<small>Swimming is good for you.</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Swimming is good for your back.</li><li>Learning a language takes time.</li><li>It’s nice to see you. <span class=\"ig-gloss\">— с it обычно to</span></li></ul><p class=\"sv-rn\">В начале предложения как подлежащее — чаще -ing. После <i>It’s + прилагательное</i> — to.</p></div></details></div></section>\n<section class=\"mv-sec\" id=\"ig-forms\"><h2><span class=\"mv-num\">9</span>Формы: раньше, в процессе, пассив</h2><p class=\"mv-lead\">Выберите время, залог и процесс — конструктор покажет форму.</p><div class=\"ig-builder\"><div class=\"ig-axis\" data-axis=\"when\"><span>Когда?</span><button type=\"button\" class=\"ig-ax on\" data-val=\"same\" aria-pressed=\"true\">одновременно или позже</button><button type=\"button\" class=\"ig-ax\" data-val=\"before\" aria-pressed=\"false\">раньше главного</button></div><div class=\"ig-axis\" data-axis=\"voice\"><span>Кто действует?</span><button type=\"button\" class=\"ig-ax on\" data-val=\"act\" aria-pressed=\"true\">сам (актив)</button><button type=\"button\" class=\"ig-ax\" data-val=\"pas\" aria-pressed=\"false\">над ним (пассив)</button></div><div class=\"ig-axis\" data-axis=\"cont\"><span>Процесс?</span><button type=\"button\" class=\"ig-ax on\" data-val=\"no\" aria-pressed=\"true\">просто факт</button><button type=\"button\" class=\"ig-ax\" data-val=\"yes\" aria-pressed=\"false\">в процессе</button></div><div class=\"ig-fbout\" aria-live=\"polite\"><div class=\"ig-fbr\" data-key=\"same-act-no\"><div class=\"ig-fbc ig-to\"><small>инфинитив</small><b>to do</b><i>She seems to know him.</i></div><div class=\"ig-fbc ig-ing\"><small>-ing</small><b>doing</b><i>I enjoy cooking.</i></div></div><div class=\"ig-fbr\" data-key=\"same-act-yes\" hidden><div class=\"ig-fbc ig-to\"><small>инфинитив</small><b>to be doing</b><i>He seems to be sleeping.</i></div><div class=\"ig-fbc ig-ing\"><small>-ing</small><b>—</b><i>У -ing нет отдельной длительной формы.</i></div></div><div class=\"ig-fbr\" data-key=\"same-pas-no\" hidden><div class=\"ig-fbc ig-to\"><small>инфинитив</small><b>to be done</b><i>I want to be told the truth.</i></div><div class=\"ig-fbc ig-ing\"><small>-ing</small><b>being done</b><i>I hate being interrupted.</i></div></div><div class=\"ig-fbr\" data-key=\"same-pas-yes\" hidden><div class=\"ig-fbc ig-to\"><small>инфинитив</small><b>to be being done</b><i>Почти не встречается: лучше переформулировать.</i></div><div class=\"ig-fbc ig-ing\"><small>-ing</small><b>—</b><i>—</i></div></div><div class=\"ig-fbr\" data-key=\"before-act-no\" hidden><div class=\"ig-fbc ig-to\"><small>инфинитив</small><b>to have done</b><i>He seems to have lost his keys.</i></div><div class=\"ig-fbc ig-ing\"><small>-ing</small><b>having done</b><i>He denied having taken the money.</i></div></div><div class=\"ig-fbr\" data-key=\"before-act-yes\" hidden><div class=\"ig-fbc ig-to\"><small>инфинитив</small><b>to have been doing</b><i>She seems to have been crying.</i></div><div class=\"ig-fbc ig-ing\"><small>-ing</small><b>—</b><i>—</i></div></div><div class=\"ig-fbr\" data-key=\"before-pas-no\" hidden><div class=\"ig-fbc ig-to\"><small>инфинитив</small><b>to have been done</b><i>The car is said to have been stolen.</i></div><div class=\"ig-fbc ig-ing\"><small>-ing</small><b>having been done</b><i>She was angry at having been ignored.</i></div></div><div class=\"ig-fbr\" data-key=\"before-pas-yes\" hidden><div class=\"ig-fbc ig-to\"><small>инфинитив</small><b>—</b><i>Такой формы на практике нет.</i></div><div class=\"ig-fbc ig-ing\"><small>-ing</small><b>—</b><i>—</i></div></div></div></div><details class=\"ig-more\"><summary>Все формы одной таблицей</summary><table class=\"ig-ftable\"><thead><tr><th></th><th>Актив</th><th>Пассив</th></tr></thead><tbody><tr><th>Инфинитив</th><td>to do<br>to be doing<br>to have done<br>to have been doing</td><td>to be done<br><br>to have been done</td></tr><tr><th>-ing</th><td>doing<br><br>having done</td><td>being done<br><br>having been done</td></tr></tbody></table></details><div class=\"sv-rows\"><details class=\"sv-row ig-to\" id=\"ig-perf-inf\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Раньше главного: to have done<small>seem · appear · is said to have done</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>He seems to have forgotten.</li><li>She claims to have met the Queen.</li><li>They are said to have married in secret.</li><li>I’m glad to have met you.</li></ul><p class=\"sv-rn\">Перфектный инфинитив показывает, что действие <b>было раньше</b> глагола-«хозяина».</p></div></details><details class=\"sv-row ig-to\" id=\"ig-cont-inf\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">В процессе: to be doing<small>seem to be doing · pretend to be doing</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>You seem to be enjoying yourself.</li><li>He pretended to be reading.</li><li>She is said to be writing a new book.</li></ul></div></details><details class=\"sv-row ig-ing\" id=\"ig-pass\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Пассив: to be done · being done<small>expect to be promoted · hate being told</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>She expects to be promoted.</li><li>I hate being told what to do.</li><li>He avoided being seen.</li><li>The documents need to be signed.</li></ul><p class=\"sv-rn\">Если с подлежащим что-то делают, нужна пассивная форма: <i>I don’t like being laughed at.</i></p></div></details><details class=\"sv-row ig-ing\" id=\"ig-perf-ger\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">Раньше: having done<small>deny having done · after having done</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>He denied having seen her.</li><li>I regret not having studied harder.</li><li>I remember meeting her. <span class=\"ig-gloss\">— обычно без having</span></li><li>Thank you for helping me. <span class=\"ig-gloss\">— обычно без having</span></li></ul><p class=\"sv-rn\">После remember, forget, regret, deny, thank, apologise for, after, on, without обычно хватает простого -ing, даже если действие было раньше.</p></div></details><details class=\"sv-row ig-ing\" id=\"ig-needs\"><summary><span class=\"sv-v ig-ing\">doing</span><span class=\"sv-rt\">needs doing · worth doing<small>-ing с пассивным смыслом</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>The windows need cleaning. = need to be cleaned</li><li>This shirt wants ironing. <span class=\"ig-gloss\">— разговорное британское</span></li><li>The film is worth seeing.</li><li>He deserves to be promoted.</li><li class=\"sv-no\"><s>It’s worth to see.</s></li></ul><p class=\"sv-rn\"><i>worth</i> — только -ing. О людях с deserve берите пассивный инфинитив: <i>deserves to be praised</i>.</p></div></details><details class=\"sv-row ig-to\" id=\"ig-unreal\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Несбывшееся в прошлом<small>meant / hoped / was to have done</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>I meant to call you, but I forgot.</li><li>I would like to have seen her face!</li><li>He was to have arrived yesterday, but his flight was cancelled.</li></ul><p class=\"sv-rn\">Перфектный инфинитив после meant, hoped, intended, was to, would like подчёркивает, что задуманное <b>не случилось</b>. Это книжный оттенок; в разговоре хватает <i>I meant to call you, but…</i></p></div></details><details class=\"sv-row ig-to\" id=\"ig-neg\"><summary><span class=\"sv-v ig-to\">to do</span><span class=\"sv-rt\">Отрицание<small>not to do · not doing</small></span></summary><div class=\"sv-rb\"><ul class=\"sv-exs\"><li>Try not to be late.</li><li>He promised not to tell anyone.</li><li>I regret not going.</li><li>She told me not to worry.</li></ul><p class=\"sv-rn\"><b>not</b> ставится прямо перед формой: not to do, not doing.</p></div></details></div></section>\n<section class=\"mv-sec\" id=\"ig-finder\"><h2><span class=\"mv-num\">10</span>Список: какой глагол что любит</h2><p class=\"mv-lead\">Отфильтруйте по форме или найдите слово.</p><div class=\"sv-filter ig-filter\" role=\"group\" aria-label=\"Какая форма\"><button type=\"button\" class=\"ig-all\" data-f=\"all\" aria-pressed=\"true\">Все</button><button type=\"button\" class=\"ig-to\" data-f=\"to\" aria-pressed=\"false\">to do</button><button type=\"button\" class=\"ig-ing\" data-f=\"ing\" aria-pressed=\"false\">doing</button><button type=\"button\" class=\"ig-bare\" data-f=\"bare\" aria-pressed=\"false\">do</button><button type=\"button\" class=\"ig-both\" data-f=\"both\" aria-pressed=\"false\">оба</button></div><label class=\"ig-search\"><span>Найти слово</span><input type=\"search\" placeholder=\"например, avoid\" autocomplete=\"off\" spellcheck=\"false\"></label><div class=\"sv-phs ig-finds\" id=\"ig-list\"><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"afford\"><summary><b>afford</b><span>to do</span></summary><p>We can’t afford to wait.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"agree\"><summary><b>agree</b><span>to do</span></summary><p>She agreed to help.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"appear\"><summary><b>appear</b><span>to do</span></summary><p>He appears to be lost.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"arrange\"><summary><b>arrange</b><span>to do</span></summary><p>We arranged to meet at five.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"ask\"><summary><b>ask</b><span>to do</span></summary><p>He asked to see the manager.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"choose\"><summary><b>choose</b><span>to do</span></summary><p>She chose to stay.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"claim\"><summary><b>claim</b><span>to do</span></summary><p>He claims to know her.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"decide\"><summary><b>decide</b><span>to do</span></summary><p>They decided to leave.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"demand\"><summary><b>demand</b><span>to do</span></summary><p>I demand to know the truth.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"deserve\"><summary><b>deserve</b><span>to do</span></summary><p>You deserve to win.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"expect\"><summary><b>expect</b><span>to do</span></summary><p>I expect to be back by six.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"fail\"><summary><b>fail</b><span>to do</span></summary><p>The bus failed to arrive.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"hesitate\"><summary><b>hesitate</b><span>to do</span></summary><p>Don’t hesitate to call.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"hope\"><summary><b>hope</b><span>to do</span></summary><p>We hope to finish soon.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"intend\"><summary><b>intend</b><span>to do</span></summary><p>I intend to apply.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"learn\"><summary><b>learn</b><span>to do</span></summary><p>She learnt to drive.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"manage\"><summary><b>manage</b><span>to do</span></summary><p>I managed to fix it.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"offer\"><summary><b>offer</b><span>to do</span></summary><p>He offered to drive.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"plan\"><summary><b>plan</b><span>to do</span></summary><p>We plan to travel.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"prepare\"><summary><b>prepare</b><span>to do</span></summary><p>Prepare to be amazed.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"pretend\"><summary><b>pretend</b><span>to do</span></summary><p>She pretended to sleep.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"promise\"><summary><b>promise</b><span>to do</span></summary><p>I promise to write.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"refuse\"><summary><b>refuse</b><span>to do</span></summary><p>He refused to pay.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"seem\"><summary><b>seem</b><span>to do</span></summary><p>You seem to be tired.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"tend\"><summary><b>tend</b><span>to do</span></summary><p>I tend to forget names.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"threaten\"><summary><b>threaten</b><span>to do</span></summary><p>They threatened to leave.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"want\"><summary><b>want</b><span>to do</span></summary><p>I want to rest.</p></details><details class=\"sv-ph ig-to\" data-v=\"to\" data-w=\"would like\"><summary><b>would like</b><span>to do</span></summary><p>I’d like to try.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"admit\"><summary><b>admit</b><span>doing</span></summary><p>He admitted lying.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"appreciate\"><summary><b>appreciate</b><span>doing</span></summary><p>I appreciate your helping.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"avoid\"><summary><b>avoid</b><span>doing</span></summary><p>Avoid eating late.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"can’t help\"><summary><b>can’t help</b><span>doing</span></summary><p>I can’t help smiling.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"can’t stand\"><summary><b>can’t stand</b><span>doing</span></summary><p>I can’t stand waiting.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"carry on\"><summary><b>carry on</b><span>doing</span></summary><p>Carry on reading.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"consider\"><summary><b>consider</b><span>doing</span></summary><p>We’re considering moving.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"delay\"><summary><b>delay</b><span>doing</span></summary><p>Don’t delay replying.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"deny\"><summary><b>deny</b><span>doing</span></summary><p>She denied knowing him.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"dislike\"><summary><b>dislike</b><span>doing</span></summary><p>I dislike flying.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"enjoy\"><summary><b>enjoy</b><span>doing</span></summary><p>We enjoyed sailing.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"fancy\"><summary><b>fancy</b><span>doing</span></summary><p>Fancy going out?</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"feel like\"><summary><b>feel like</b><span>doing</span></summary><p>I feel like dancing.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"finish\"><summary><b>finish</b><span>doing</span></summary><p>Finish eating first.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"give up\"><summary><b>give up</b><span>doing</span></summary><p>He gave up smoking.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"imagine\"><summary><b>imagine</b><span>doing</span></summary><p>Imagine living there!</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"involve\"><summary><b>involve</b><span>doing</span></summary><p>It involves travelling.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"keep\"><summary><b>keep</b><span>doing</span></summary><p>Keep going!</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"mention\"><summary><b>mention</b><span>doing</span></summary><p>He mentioned seeing you.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"mind\"><summary><b>mind</b><span>doing</span></summary><p>Do you mind waiting?</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"miss\"><summary><b>miss</b><span>doing</span></summary><p>I miss living there.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"postpone\"><summary><b>postpone</b><span>doing</span></summary><p>They postponed leaving.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"practise\"><summary><b>practise</b><span>doing</span></summary><p>Practise speaking.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"put off\"><summary><b>put off</b><span>doing</span></summary><p>Don’t put off studying.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"quit\"><summary><b>quit</b><span>doing</span></summary><p>She quit drinking coffee.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"recommend\"><summary><b>recommend</b><span>doing</span></summary><p>I recommend trying it.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"resist\"><summary><b>resist</b><span>doing</span></summary><p>I couldn’t resist buying it.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"risk\"><summary><b>risk</b><span>doing</span></summary><p>Don’t risk losing it.</p></details><details class=\"sv-ph ig-ing\" data-v=\"ing\" data-w=\"suggest\"><summary><b>suggest</b><span>doing</span></summary><p>I suggest waiting.</p></details><details class=\"sv-ph ig-bare\" data-v=\"bare\" data-w=\"can / must / should\"><summary><b>can / must / should</b><span>do</span></summary><p>You should rest.</p></details><details class=\"sv-ph ig-bare\" data-v=\"bare\" data-w=\"make sb\"><summary><b>make sb</b><span>do</span></summary><p>It made me laugh.</p></details><details class=\"sv-ph ig-bare\" data-v=\"bare\" data-w=\"let sb\"><summary><b>let sb</b><span>do</span></summary><p>Let me see.</p></details><details class=\"sv-ph ig-bare\" data-v=\"bare\" data-w=\"had better\"><summary><b>had better</b><span>do</span></summary><p>You’d better go.</p></details><details class=\"sv-ph ig-bare\" data-v=\"bare\" data-w=\"would rather\"><summary><b>would rather</b><span>do</span></summary><p>I’d rather stay.</p></details><details class=\"sv-ph ig-bare\" data-v=\"bare\" data-w=\"why not\"><summary><b>why not</b><span>do</span></summary><p>Why not try?</p></details><details class=\"sv-ph ig-both\" data-v=\"both\" data-w=\"begin / start\"><summary><b>begin / start</b><span>to / -ing</span></summary><p>It began to rain / raining.</p></details><details class=\"sv-ph ig-both\" data-v=\"both\" data-w=\"continue\"><summary><b>continue</b><span>to / -ing</span></summary><p>He continued to talk / talking.</p></details><details class=\"sv-ph ig-both\" data-v=\"both\" data-w=\"love / hate / prefer\"><summary><b>love / hate / prefer</b><span>to / -ing</span></summary><p>I love to dance / dancing.</p></details><details class=\"sv-ph ig-both\" data-v=\"both\" data-w=\"help (sb)\"><summary><b>help (sb)</b><span>to / -ing</span></summary><p>Help me (to) carry it.</p></details><details class=\"sv-ph ig-both\" data-v=\"both\" data-w=\"remember / forget\"><summary><b>remember / forget</b><span>to / -ing</span></summary><p>Смысл меняется: раздел 6.</p></details><details class=\"sv-ph ig-both\" data-v=\"both\" data-w=\"stop / try / regret\"><summary><b>stop / try / regret</b><span>to / -ing</span></summary><p>Смысл меняется: раздел 6.</p></details></div><p class=\"ig-none\" hidden>Такого слова в списке нет. Проверьте его в словаре: Oxford и Cambridge показывают схему [+ to infinitive] или [+ -ing].</p></section>\n<section class=\"mv-sec\" id=\"ig-traps\"><h2><span class=\"mv-num\">11</span>Ловушки</h2><p class=\"mv-lead\">Нажмите на карточку, чтобы увидеть, как правильно.</p><div class=\"sv-traps\"><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">I enjoy to swim.</span><span class=\"sv-tr-good\">I enjoy swimming.</span><small>enjoy — только -ing.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">I’m looking forward to see you.</span><span class=\"sv-tr-good\">I’m looking forward to seeing you.</span><small>to здесь предлог.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">She suggested me to go.</span><span class=\"sv-tr-good\">She suggested (that) I go.</span><small>Или: She suggested going.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">They made me to wait.</span><span class=\"sv-tr-good\">They made me wait.</span><small>make sb do — без to.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">You must to go.</span><span class=\"sv-tr-good\">You must go.</span><small>После модальных — без to.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">I want that you come.</span><span class=\"sv-tr-good\">I want you to come.</span><small>want sb to do.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">I’m used to get up early.</span><span class=\"sv-tr-good\">I’m used to getting up early.</span><small>be used to + -ing — «привык».</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">He came here for learning English.</span><span class=\"sv-tr-good\">He came here to learn English.</span><small>Цель человека — to do.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">Why to wait?</span><span class=\"sv-tr-good\">Why wait?</span><small>why / why not + глагол без to.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">The museum is worth to visit.</span><span class=\"sv-tr-good\">The museum is worth visiting.</span><small>worth — только -ing.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">You’d better to hurry.</span><span class=\"sv-tr-good\">You’d better hurry.</span><small>had better — без to.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">He isn’t enough old to drive.</span><span class=\"sv-tr-good\">He isn’t old enough to drive.</span><small>enough — после прилагательного.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">I’d like going with you.</span><span class=\"sv-tr-good\">I’d like to go with you.</span><small>would like — только to.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">The room needs clean.</span><span class=\"sv-tr-good\">The room needs cleaning.</span><small>Или: needs to be cleaned.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">Let me to explain.</span><span class=\"sv-tr-good\">Let me explain.</span><small>let sb do — без to.</small></button><button type=\"button\" class=\"sv-trap\" aria-expanded=\"false\"><span class=\"sv-tr-bad\">I stopped to smoke last year.</span><span class=\"sv-tr-good\">I stopped smoking last year.</span><small>Бросил — stop doing.</small></button></div></section>\n<section class=\"mv-sec\" id=\"ig-check\"><h2><span class=\"mv-num\">12</span>Проверьте себя</h2><p class=\"mv-lead\">Двенадцать коротких вопросов.</p><div class=\"sv-quiz\"><div class=\"sv-q\"><p class=\"sv-qs\">We decided <span class=\"sv-gap\">___</span> a taxi.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\" data-ok=\"1\">to take</button><button type=\"button\" class=\"ig-q1\">take</button><button type=\"button\" class=\"ig-q2\">taking</button><button type=\"button\" class=\"ig-q3\">to taking</button></div><p class=\"sv-why\" hidden>decide + to do.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">Do you mind <span class=\"sv-gap\">___</span> the window?</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">to open</button><button type=\"button\" class=\"ig-q1\">open</button><button type=\"button\" class=\"ig-q2\" data-ok=\"1\">opening</button><button type=\"button\" class=\"ig-q3\">to opening</button></div><p class=\"sv-why\" hidden>mind + -ing.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">The teacher made us <span class=\"sv-gap\">___</span> the text again.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">to read</button><button type=\"button\" class=\"ig-q1\" data-ok=\"1\">read</button><button type=\"button\" class=\"ig-q2\">reading</button><button type=\"button\" class=\"ig-q3\">to reading</button></div><p class=\"sv-why\" hidden>make sb do — без to.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">I’m looking forward to <span class=\"sv-gap\">___</span> my cousins.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">to see</button><button type=\"button\" class=\"ig-q1\">see</button><button type=\"button\" class=\"ig-q2\" data-ok=\"1\">seeing</button><button type=\"button\" class=\"ig-q3\">saw</button></div><p class=\"sv-why\" hidden>look forward to + -ing.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">Remember <span class=\"sv-gap\">___</span> the plants while I’m away!</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\" data-ok=\"1\">to water</button><button type=\"button\" class=\"ig-q1\">water</button><button type=\"button\" class=\"ig-q2\">watering</button><button type=\"button\" class=\"ig-q3\">to watering</button></div><p class=\"sv-why\" hidden>Не забудь сделать — remember to do.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">I’ll never forget <span class=\"sv-gap\">___</span> the Northern Lights.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">to see</button><button type=\"button\" class=\"ig-q1\">see</button><button type=\"button\" class=\"ig-q2\" data-ok=\"1\">seeing</button><button type=\"button\" class=\"ig-q3\">to seeing</button></div><p class=\"sv-why\" hidden>Воспоминание о прошлом — forget doing.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">He left without <span class=\"sv-gap\">___</span> a word.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">to say</button><button type=\"button\" class=\"ig-q1\">say</button><button type=\"button\" class=\"ig-q2\" data-ok=\"1\">saying</button><button type=\"button\" class=\"ig-q3\">said</button></div><p class=\"sv-why\" hidden>После предлога — -ing.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">You’d better <span class=\"sv-gap\">___</span> a coat.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">to take</button><button type=\"button\" class=\"ig-q1\" data-ok=\"1\">take</button><button type=\"button\" class=\"ig-q2\">taking</button><button type=\"button\" class=\"ig-q3\">took</button></div><p class=\"sv-why\" hidden>had better + глагол без to.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">This film is worth <span class=\"sv-gap\">___</span>.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">to watch</button><button type=\"button\" class=\"ig-q1\">watch</button><button type=\"button\" class=\"ig-q2\" data-ok=\"1\">watching</button><button type=\"button\" class=\"ig-q3\">to be watched</button></div><p class=\"sv-why\" hidden>worth + -ing.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">The roof needs <span class=\"sv-gap\">___</span>.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">repair</button><button type=\"button\" class=\"ig-q1\">to repair</button><button type=\"button\" class=\"ig-q2\" data-ok=\"1\">repairing</button><button type=\"button\" class=\"ig-q3\">repaired</button></div><p class=\"sv-why\" hidden>Вещь нуждается: needs doing.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">He seems <span class=\"sv-gap\">___</span> his phone again.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">to lose</button><button type=\"button\" class=\"ig-q1\" data-ok=\"1\">to have lost</button><button type=\"button\" class=\"ig-q2\">losing</button><button type=\"button\" class=\"ig-q3\">having lost</button></div><p class=\"sv-why\" hidden>Потерял раньше — to have done.</p></div><div class=\"sv-q\"><p class=\"sv-qs\">I hate <span class=\"sv-gap\">___</span> when I’m working.</p><div class=\"sv-opts ig-opts\"><button type=\"button\" class=\"ig-q0\">interrupting</button><button type=\"button\" class=\"ig-q1\">to interrupt</button><button type=\"button\" class=\"ig-q2\" data-ok=\"1\">being interrupted</button><button type=\"button\" class=\"ig-q3\">interrupt</button></div><p class=\"sv-why\" hidden>Меня прерывают — пассив: being interrupted.</p></div></div></section>\n</div>";
function infinitiveGerundRuleHtml(prefix='') {
  const safePrefix=String(prefix).replace(/[^a-zA-Z0-9_-]/g,'');
  return INFINITIVE_GERUND_RULE_CONTENT
    .replace(/id="([^"]+)"/g,(_,id)=>'id="'+safePrefix+id+'" data-ig-id="'+id+'"')
    .replace(/href="#(ig-[^"]+)"/g,(_,id)=>'href="#theory/infinitive/'+id+'" data-ig-anchor="'+id+'"');
}
function revealInfinitiveGerundAnchor(container,anchor) {
  const root=container?.matches?.('.ig')?container:container?.querySelector?.('.ig');
  if(!root)return;
  const id=String(anchor||'').replace(/^#?(?:theory\/infinitive\/)?/,'');
  if(!id)return;
  const target=[root,...root.querySelectorAll('[data-ig-id]')].find(node=>node.dataset.igId===id||node.id===id);
  if(!target)return;
  for(let node=target.closest('details');node;node=node.parentElement?.closest('details'))node.open=true;
  const spot=target.closest('details')||target.closest('.ig-pair')||target.closest('.mv-sec')||target;
  const scrollArea=root.closest('.reference-reader,.rule-dialog-content');
  if(scrollArea){
    const nav=root.querySelector('.mv-nav');
    scrollArea.scrollTop+=spot.getBoundingClientRect().top-scrollArea.getBoundingClientRect().top-(nav?.getBoundingClientRect().height||0)-16;
  }else spot.scrollIntoView({block:'start',behavior:'instant'});
  if(spot.classList?.contains('ig-pair')){spot.classList.add('ig-flash');setTimeout(()=>spot.classList.remove('ig-flash'),1200);}
}
function igPick(group,selector,el){
  group.querySelectorAll(selector).forEach(b=>{const on=b===el;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));});
}
function igFilter(sec){
  const pill=sec.querySelector('.ig-filter [aria-pressed="true"]');
  const f=pill?pill.dataset.f:'all';
  const q=(sec.querySelector('.ig-search input')?.value||'').trim().toLowerCase();
  let shown=0;
  sec.querySelectorAll('.sv-ph').forEach(p=>{
    const hide=(f!=='all'&&p.dataset.v!==f)||(q&&!p.dataset.w.includes(q));
    p.hidden=hide;if(hide)p.open=false;else shown++;
  });
  const none=sec.querySelector('.ig-none');if(none)none.hidden=shown>0;
}
function initialiseInfinitiveGerundRule(container) {
  const root=container?.matches?.('.ig')?container:container?.querySelector?.('.ig');
  if(!root||root.dataset.initialised)return;
  root.dataset.initialised='true';
  root.addEventListener('input',event=>{
    const input=event.target.closest?.('.ig-search input');
    if(input&&root.contains(input))igFilter(input.closest('.mv-sec'));
  });
  root.addEventListener('click',event=>{
    const t=event.target;
    const link=t.closest?.('[data-ig-anchor]');
    if(link&&root.contains(link)&&event.button===0&&!event.metaKey&&!event.ctrlKey&&!event.altKey&&!event.shiftKey){
      event.preventDefault();event.stopPropagation();revealInfinitiveGerundAnchor(root,link.dataset.igAnchor);return;
    }
    const lens=t.closest?.('.sv-lens');
    if(lens&&root.contains(lens)){
      igPick(lens.parentElement,'.sv-lens',lens);
      root.querySelectorAll('.sv-lp').forEach(p=>{p.hidden=p.dataset.v!==lens.dataset.v;});
      return;
    }
    const slot=t.closest?.('.sv-slot');
    if(slot&&root.contains(slot)){
      const board=slot.closest('.sv-board');
      igPick(slot.parentElement,'.sv-slot',slot);
      board.querySelectorAll('.sv-sd').forEach(d=>{d.hidden=d.dataset.s!==slot.dataset.s;});
      return;
    }
    const pb=t.closest?.('.ig-pb');
    if(pb&&root.contains(pb)){
      const pair=pb.closest('.ig-pair');
      igPick(pb.parentElement,'.ig-pb',pb);
      pair.querySelectorAll('.ig-pp').forEach(p=>{p.hidden=p.dataset.k!==pb.dataset.k;});
      return;
    }
    const ax=t.closest?.('.ig-ax');
    if(ax&&root.contains(ax)){
      const b=ax.closest('.ig-builder');
      igPick(ax.parentElement,'.ig-ax',ax);
      const val=name=>b.querySelector('[data-axis="'+name+'"] .ig-ax.on')?.dataset.val;
      const key=val('when')+'-'+val('voice')+'-'+val('cont');
      b.querySelectorAll('.ig-fbr').forEach(r=>{r.hidden=r.dataset.key!==key;});
      return;
    }
    const pill=t.closest?.('.ig-filter button');
    if(pill&&root.contains(pill)){
      pill.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===pill)));
      igFilter(pill.closest('.mv-sec'));return;
    }
    const trap=t.closest?.('.sv-trap');
    if(trap&&root.contains(trap)){
      const on=!trap.classList.contains('on');
      trap.classList.toggle('on',on);trap.setAttribute('aria-expanded',String(on));return;
    }
    const option=t.closest?.('.sv-opts button');
    if(option&&root.contains(option)){
      const q=option.closest('.sv-q');
      if(q.classList.contains('done'))return;
      const right=option.hasAttribute('data-ok');
      q.classList.add('done',right?'ok':'bad');
      q.querySelectorAll('.sv-opts button').forEach(b=>{b.disabled=true;if(b.hasAttribute('data-ok'))b.classList.add('sv-right');});
      if(!right)option.classList.add('sv-wrong');
      const gap=q.querySelector('.sv-gap');if(gap)gap.textContent=q.querySelector('[data-ok]').textContent;
      q.querySelector('.sv-why').hidden=false;
      const quiz=q.closest('.sv-quiz');
      const all=quiz.querySelectorAll('.sv-q'),done=quiz.querySelectorAll('.sv-q.done');
      if(all.length===done.length){
        let foot=quiz.querySelector('.sv-score');
        if(!foot){foot=document.createElement('div');foot.className='sv-score';quiz.append(foot);}
        foot.replaceChildren();
        const text=document.createElement('span');text.textContent='Результат: '+quiz.querySelectorAll('.sv-q.ok').length+' из '+all.length;
        const again=document.createElement('button');again.type='button';again.className='sv-again';again.textContent='Ещё раз';
        foot.append(text,again);
      }
      return;
    }
    const again=t.closest?.('.sv-again');
    if(again&&root.contains(again)){
      const quiz=again.closest('.sv-quiz');
      quiz.querySelectorAll('.sv-q').forEach(q=>{q.classList.remove('done','ok','bad');q.querySelector('.sv-why').hidden=true;const g=q.querySelector('.sv-gap');if(g)g.textContent='___';q.querySelectorAll('button').forEach(b=>{b.disabled=false;b.classList.remove('sv-right','sv-wrong');});});
      quiz.querySelector('.sv-score')?.remove();
    }
  });
}
